import{_ as a,o as r,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Часто Задаваемые Вопросы (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"ru/96-常见问题FAQ.md","filePath":"ru/96-常见问题FAQ.md","lastUpdated":1789183869000}'),e={name:"ru/96-常见问题FAQ.md"};function i(s,t,l,d,h,p){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="часто-задаваемые-вопросы-faq" tabindex="-1">Часто Задаваемые Вопросы (FAQ) <a class="header-anchor" href="#часто-задаваемые-вопросы-faq" aria-label="Permalink to &quot;Часто Задаваемые Вопросы (FAQ)&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>96</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>часто задаваемые вопросы, FAQ, ответы на вопросы, разъяснения по сеттингу, руководство для начинающих</td></tr></tbody></table><h2 id="i-пояснения" tabindex="-1">I. Пояснения <a class="header-anchor" href="#i-пояснения" aria-label="Permalink to &quot;I. Пояснения&quot;">​</a></h2><p>Настоящий документ собрает частые вопросы и ответы о системе сеттинга Симбиотической Цивилизации Якоря, сгруппированные по темам. Вопросы охватывают все аспекты: основные концепции мировоззрения, систему культивации, общественный строй, правовую систему, межплоскостное взаимодействие, правила времени и др. Цель настоящего документа — дать читателям, впервые знакомящимся с сеттингом Симбиотической Цивилизации Якоря, быстрое руководство для вхождения, а также предоставить углублённым исследователям авторитетные ответы на частые вопросы. Настоящий документ является динамически обновляемым; новые вопросы и ответы будут непрерывно добавляться на основе отзывов читателей.</p><h2 id="ii-мировоззрение-и-основные-концепции" tabindex="-1">II. Мировоззрение и основные концепции <a class="header-anchor" href="#ii-мировоззрение-и-основные-концепции" aria-label="Permalink to &quot;II. Мировоззрение и основные концепции&quot;">​</a></h2><p><strong>В1: Какова центральная идея Симбиотической Цивилизации Якоря?</strong> О: Центральная идея Симбиотической Цивилизации Якоря — «против хищничества, за симбиоз». Конкретно, она выступает против хищнических систем культивации, осуществляемых ценой пожирания энергии, удачи или даже истока слабых, и выступает за совместную эволюцию через симбиотическое сотрудничество. Основная концепция цивилизации — «вернуть всем живым существам право выбора судьбы и эволюции», а её основные принципы — «больше труда — больше выгоды; самовоспроизводство и самостоятельный рост; путь для каждого; совместное продвижение Десяти Тысяч Рас».</p><p><strong>В2: Что означает принцип «Реальность как основа»?</strong> О: «Реальность как основа» — одна из фундаментальных позиций Симбиотической Цивилизации Якоря, означающая, что реальный мир является единственным настоящим миром, а мир художественных произведений — это гипотетический мысленный эксперимент. При построении сеттинга недостающее в вымысле дополняется реальностью, а то, чего нет в реальности, создаётся путём улучшения на основе объективных законов. Этот принцип обеспечивает логическую самосогласованность и реальную осязаемость системы сеттинга, избегая разрушения сеттинга, вызванного чистой фантазией.</p><p><strong>В3: Как соотносятся Вселенная Хэнъюань и вселенная?</strong> О: Полное название Вселенной Хэнъюань — «Изначальная Вселенная Ваньлин Хэнмао». Это вся совокупность вселенной, населённой и управляемой Симбиотической Цивилизацией Якоря. Это не обычная единая физическая вселенная, а составное образование из четырёх уровней — материальных плоскостей, энергетических слоёв, области сознания и сети законов. Можно понимать так: Вселенная Хэнъюань — это суперсистема вселенной, содержащая бесчисленные плоскости, с механизмом Якоря как центральным средством регулирования.</p><h2 id="iii-система-культивации" tabindex="-1">III. Система культивации <a class="header-anchor" href="#iii-система-культивации" aria-label="Permalink to &quot;III. Система культивации&quot;">​</a></h2><p><strong>В4: Откуда взялись Триста Исходных Систем Культивации?</strong> О: Триста Систем — это не выдуманные человеком техники, а ортодоксальные пути культивации, непосредственно извлечённые из исходных законов вселенной и проверенные Якорями. В Период установления симбиотической системы команда под руководством «Саньбай Ши» провела систематическое вскрытие и систематизацию законов вселенной, в итоге обобщив Триста систем культивации, охватывающих все измерения эволюции. Эти системы делятся на шесть больших категорий — исходная дедукция, жизненный цикл, пространственные правовые принципы, возвышение сознания, симбиотическая сеть и прикладная инженерия — по пятьдесят систем в каждой категории.</p><p><strong>В5: Почему первые три системы называются «Тремя Исходными Основами»?</strong> О: Первые три системы — Дедуктивная Итерация (система № 1), Жизненный Цикл (система № 2) и Регулирование Пространственных Правовых Принципов (система № 3) — являются культивационной основой всех остальных систем. Система Дедуктивной Итерации обеспечивает основу мудрости и методологии; Система Жизненного Цикла обеспечивает основу жизненной энергии; Система Регулирования Пространственных Правовых Принципов обеспечивает основу пространственных и законных операций. Культиваторам любых других систем рекомендуется сначала практиковать хотя бы одну из Трёх Исходных Основ, чтобы заложить прочный эволюционный фундамент.</p><p><strong>В6: Что такое Плод Умножения? Как он связан с One Piece?</strong> О: Плод Умножения — один из «стартовых баффов» Симбиотической Цивилизации Якоря, происходящий из сеттинга Плода Умножения мира One Piece. Во Вселенной Хэнъюань Плод Умножения получил технологическое применение: он может стократно повысить дедуктивную способность культиватора и является центральным вспомогательным инструментом Системы Дедуктивной Итерации. Этот сеттинг воплощает принцип «недостающее в вымысле дополнять реальностью, а отсутствующее в реальности создавать улучшением на основе законов» — интересные сеттинги художественных произведений после законопреобразующей адаптации включаются в технологическую систему симбиотической цивилизации.</p><p><strong>В7: Что такое Стратегия активации 20 %? Почему 20 %?</strong> О: Стратегия активации 20 % — поэтапная стратегическая цель Симбиотической Цивилизации Якоря, направленная на активацию на раннем этапе 20 % всех живых существ вселенной в Верховные Силачи Плоскости. Выбор 20 % основан на динамическом анализе симбиотической сети — когда 20 % узлов сети достигают высокоэнергетического состояния, общий резонансный эффект сети запускает критическую точку, влекущую ускоренную эволюцию остальных 80 % узлов. Эти 20 % Верховных Силачей Плоскости станут костяком сил и сыграют центральную роль в обслуживании Якорей, наставническом руководстве и строительстве цивилизации.</p><h2 id="iv-общественныи-строи-и-право" tabindex="-1">IV. Общественный строй и право <a class="header-anchor" href="#iv-общественныи-строи-и-право" aria-label="Permalink to &quot;IV. Общественный строй и право&quot;">​</a></h2><p><strong>В8: Что такое Пять типов симбиотических цивилизаций?</strong> О: Пять типов симбиотических цивилизаций — пять типов симбиотических обществ, определённых на основе характеристик цивилизаций реального мира: восточноазиатский интенсивный тип (характеризуется высокоэффективной организацией и коллективизмом), скандинавский социальный тип (характеризуется высоким благосостоянием и социальным равенством), североамериканский плюралистический тип (характеризуется многообразием культур и инновационной энергией), континентальный европейский социальный тип (характеризуется социальной рыночной экономикой и участием трудящихся) и развивающийся догоняющий тип (характеризуется быстрым развитием и преимуществами догоняющего). Эти пять типов — не взаимоисключающие классификации, а эталонные модели, которые могут заимствовать друг у друга и развиваться через слияние.</p><p><strong>В9: Как работает Механизм подряда, связанного с результатом?</strong> О: Механизм подряда, связанного с результатом, — центральная система распределения ресурсов Симбиотической Цивилизации Якоря, вдохновлённая реальной системой семейного подряда, связанного с результатом. Порядок её работы таков: ресурсы культивации вселенной распределяются между индивидами или группами в форме «подряда»; подрядчики получают право пользования и право на выгоду от ресурсов через труд и вклад. Больше труда — больше выгоды: чем больше вклад, тем больше ресурсов получено. Этот механизм одновременно гарантирует справедливое распределение ресурсов и стимулирует трудовую инициативу индивидов, реализуя единство справедливости и эффективности.</p><p><strong>В10: Как соотносятся Симбиотическая Конституция и обычные законы?</strong> О: Симбиотическая Конституция — основной закон Симбиотической Цивилизации Якоря, обладающий высшей юридической силой. Все законы, административные акты и местные нормативные акты не должны противоречить Конституции. Симбиотический Трудовой Закон, Закон о защите прав потребителей и пять сопроводительных законов об образовании, здравоохранении, жилье, окружающей среде и антимонопольном регулировании — всё это отраслевые законы, принятые на законодательной основе Симбиотической Конституции, призванные конкретизировать и сделать операциональными принципиальные положения Конституции. Симбиотический Суд имеет право осуществлять конституционный надзор за законами, противоречащими Конституции, и объявлять их недействительными.</p><h2 id="v-межплоскостное-взаимодеиствие" tabindex="-1">V. Межплоскостное взаимодействие <a class="header-anchor" href="#v-межплоскостное-взаимодеиствие" aria-label="Permalink to &quot;V. Межплоскостное взаимодействие&quot;">​</a></h2><p><strong>В11: Что такое археологическая схема «Зеркало Репликации + изолированное пространство + передача только знаний»?</strong> О: Это стандартная схема межплоскостной археологии и археологии возврата времени Симбиотической Цивилизации Якоря, состоящая из трёх ключевых элементов:</p><ol><li><strong>Зеркало Репликации</strong>: осуществляет полную копию 1:1 археологической цели, не соприкасаясь с оригиналом; процесс копирования не изменяет никакого состояния оригинала.</li><li><strong>Изолированное пространство</strong>: копия создаётся в независимом пространстве, полностью изолированном от цели; археологи проводят все исследовательские операции в изолированном пространстве.</li><li><strong>Передача только знаний</strong>: после завершения археологии могут быть переданы только абстрактные знания и информация; материя и энергия копии должны быть уничтожены в изолированном пространстве и не могут быть принесены в родную плоскость. Эта схема гарантирует нулевое вмешательство археологического процесса в целевую плоскость или целевой период, одновременно предотвращая межплоскостное загрязнение.</li></ol><p><strong>В12: Почему необходимо соблюдать принцип «сначала наблюдение, потом ограниченное вмешательство»?</strong> О: Центральная идея этого принципа — «когнитивное смирение»: даже Верховный Силач Плоскости не может полностью постичь все причинные связи временного узла или цивилизации плоскости. Любое прямое вмешательство в прошлое или в иную плоскость может вызвать непредсказуемые причинные цепные реакции. Поэтому сначала необходимо провести всестороннее наблюдение с максимально осторожным отношением, и лишь когда данных наблюдения достаточно и оценка рисков ясна, разрешается ограниченное вмешательство, строго ограниченное по охвату и степени. Этот принцип является фундаментальной гарантией безопасности возврата времени и межплоскостных операций.</p><p><strong>В13: Какие условия необходимы для межплоскостного перемещения?</strong> О: Перемещение между плоскостями требует следующих условий: во-первых, путешественник должен обладать культивацией не ниже третьей ступени Системы Регулирования Пространственных Правовых Принципов (Стадия Хуакун) или перевозиться транспортным средством, соответствующим стандартам; во-вторых, необходимо получить разрешение на перемещение соответствующего уровня, выданное Управлением Плоскостей (уровень A — археологическое наблюдение, уровень B — академический обмен, уровень C — ресурсное сотрудничество, уровень D — экстренное вмешательство); в-третьих, и начальная, и конечная точки должны иметь Якоря для калибровки координат; в-четвёртых, необходимо пройти три процедуры очищения (биологическое очищение, энергетическое очищение, очищение сознания); в-пятых, энергия перемещения должна переноситься самим путешественником, извлекать её из целевой плоскости запрещено.</p><h2 id="vi-правила-времени" tabindex="-1">VI. Правила времени <a class="header-anchor" href="#vi-правила-времени" aria-label="Permalink to &quot;VI. Правила времени&quot;">​</a></h2><p><strong>В14: В чём разница между возвратом времени и путешествием во времени?</strong> О: В сеттинге Вселенной Хэнъюань возврат времени не равен путешествию во времени. Возвращающийся во времени не входит в прошлое в полной материальной форме, а прибывает к целевому временному узлу в форме проекции сознания или информационного пакета. Существование возвращающегося в прошлом периоде «полупрозрачно» — его можно наблюдать, но физическая способность взаимодействия строго ограничена. Эта конструкция сама по себе является частью механизма безопасности возврата времени, снижая возможность физического вмешательства возвращающегося в прошлое.</p><p><strong>В15: Какие типы временных парадоксов существуют? Как их предотвращать и контролировать?</strong> О: Временные парадоксы делятся на четыре больших типа: парадокс отцеубийства (действия возвращающегося устраняют причинные условия собственного существования), информационный парадокс (информация, переданная из будущего в прошлое, образует информационный цикл без источника), онтологический парадокс (взаимодействие возвращающегося со своим прошлым «я» вызывает спутанность онтологического сознания) и событийный парадокс (возвращающийся изменяет ключевые исторические события, вызывая реконструкцию причинной цепи). Механизмы предотвращения и контроля включают: предварительную причинную оценку до возврата и причинную изоляцию возвращающегося до операции, систему белого списка вмешательств во время операции, мониторинг причинности в реальном времени и трёхуровневую экстренную реакцию во время операции, причинный ремонт и аудит после операции. Цель всей системы предотвращения и контроля — уничтожить парадоксы в зародыше.</p><h2 id="vii-жизнь-и-расы" tabindex="-1">VII. Жизнь и расы <a class="header-anchor" href="#vii-жизнь-и-расы" aria-label="Permalink to &quot;VII. Жизнь и расы&quot;">​</a></h2><p><strong>В16: Что такое аномальная жизнь и аномальная энергия?</strong> О: Аномальная жизнь — это формы жизни, не соответствующие обычному определению жизни и обладающие особыми формами существования, например, чисто энергетическая жизнь, жизнь в форме сознания, механическая жизнь. Аномальная энергия — это формы энергии, не соответствующие обычной классификации энергии и обладающие особыми свойствами и моделями поведения, например, энергия законов, энергия сознания, причинная энергия. Для этих двух типов особых существований Симбиотическая Цивилизация Якоря создала три типа стандартизированных процедур обращения (идентификация и классификация, оценка и контроль, интеграция и симбиоз), обеспечивающих их надлежащее управление и рациональное использование в рамках симбиотической цивилизации.</p><p><strong>В17: Что такое тёмная замещающая сущность? В чём состоит Этика Двойной Души?</strong> О: Тёмная замещающая сущность — особая форма жизни, в теле которой одновременно существуют две души — обычно родная душа и внешняя «замещающая» душа. Это состояние порождает сложные этические вопросы: обе души имеют свои права и личности, и одну из них нельзя просто устранить. Ядро Этки Двойной Души — уважать права каждой из двух душ и запрещать принудительное слияние или одностороннее устранение. В зависимости от конкретной ситуации тёмные замещающие сущности делятся на четыре ветви, для каждой из которых применяется свой подход: тип сосуществования (две души гармонично сосуществуют), тип чередования (две души поочерёдно управляют телом), тип разделения (две души разделяются на разные носители техническими средствами) и тип слияния (глубокое слияние в новую душу на основе добровольности обеих сторон).</p><h2 id="viii-методология-сеттинга" tabindex="-1">VIII. Методология сеттинга <a class="header-anchor" href="#viii-методология-сеттинга" aria-label="Permalink to &quot;VIII. Методология сеттинга&quot;">​</a></h2><p><strong>В18: Чем эта система сеттинга отличается от обычных сеттингов веб-романов?</strong> О: Наибольшее отличие системы сеттинга Симбиотической Цивилизации Якоря — её центральная позиция «анти-хищничество». Обычные сеттинги веб-романов часто ставят в центр личный рост и повышение силы протагониста, и система культивации там по сути хищническая — протагонист становится сильнее через пожирание, битвы и захват ресурсов. Симбиотическая Цивилизация Якоря принципиально противостоит этой модели и выступает за совместную эволюцию Десяти Тысяч Рас через симбиотическое сотрудничество. Кроме того, эта система сеттинга подчёркивает «Реальность как основу»: все установки стремятся к логической самосогласованности и соответствию объективным законам, избегая чистой фантазии и разрушения сеттинга.</p><p><strong>В19: Что конкретно представляет собой Четырёхэтапный Путь Возвышения?</strong> О: Четырёхэтапный Путь Возвышения — стратегический маршрут общего возвышения Вселенной Хэнъюань:</p><ol><li><strong>Основание реальности</strong>: установить симбиотический общественный строй на материальных плоскостях, устранить корень хищничества и завершить строительство институционального фундамента цивилизации.</li><li><strong>Технологическое усиление</strong>: соединить законы культивации с технологической инженерией, снизить порог эволюции и совершить скачок производительных сил.</li><li><strong>Эволюция сознания</strong>: способствовать миграции форм жизни в область сознания, реализуя симбиоз и сублимацию на духовном уровне.</li><li><strong>Межзвёздный симбиоз</strong>: создать полную сеть Якорей через плоскости и звёзды, завершив общее возвышение вселенной. В настоящее время Вселенная Хэнъюань находится в переломный период перехода от первого этапа ко второму.</li></ol><p><strong>В20: Как можно участвовать в расширении этой системы сеттинга?</strong> О: Система сеттинга Симбиотической Цивилизации Якоря — открытая, непрерывно расширяющаяся система. Любой человек может создавать расширения на основе существующего каркаса, включая, но не ограничиваясь: детализацией конкретных методов той или иной системы культивации, созданием культуры и истории той или иной расы, проектированием формы цивилизации той или иной плоскости, написанием подробных событий того или иного исторического периода, разработкой новых технологий и сценариев применения. Расширения сеттинга должны следовать принципу «Реальность как основа, улучшение через законы», обеспечивая логическую самосогласованность с существующим сеттингом. Отличные расширения после проверки могут быть включены в официальную систему сеттинга.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>FAQ — это быстрый вход в мир сеттинга Симбиотической Цивилизации Якоря. Через эти двадцать вопросов и ответов читатели могут быстро охватить основные концепции, ключевые механизмы и базовый каркас системы сеттинга. Конечно, FAQ не может покрыть все детали системы сеттинга; для глубокого понимания необходимо читать специализированные документы каждого модуля. По мере обогащения системы сеттинга этот FAQ будет также непрерывно обновляться, всегда оставаясь надёжным справочником для вхождения читателей и ответов на вопросы.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Хэн Юаньчжоу: Обзор Вселенной)</li><li>90-术语词典 (Словарь Терминов)</li><li>98-扩展设定建议清单 (Список Предложений по Расширенным Настройкам)</li></ul>',37)])])}const u=a(e,[["render",i]]);export{c as __pageData,u as default};
